// Assistant wire types (plan Phase 2 / S1, S1.5 "Shared schema"): briefing snapshots and the durable
// assistant runs that produce them. THE one source of these shapes and enum constants: the server
// store/service/routes and the web client import them from here, never redeclare them.
//   - Schema version is the integer ASSISTANT_SCHEMA_VERSION (the SQLite `user_version`).
//   - Timestamps are UTC ISO 8601 strings; a nullable field is an explicit `null`, never absent.
//   - Ids are `crypto.randomUUID()` values; request ids are generated by the browser once per
//     intentional action and reused on an HTTP retry.
// No response carries raw model output, stderr, credentials or local filesystem paths.
import type { Source } from "./types.js";
import type { ExtractionStatus } from "./sheet.js";

/** SQLite `PRAGMA user_version` of the assistant store (and the version of every stored snapshot). */
export const ASSISTANT_SCHEMA_VERSION = 1;

/** The briefing shows at most this many items; the rest are counted in `omittedCount`. */
export const BRIEFING_ITEM_CAP = 25;

/** One assistant run's logical deadline (S1.5 "Work and recovery"). */
export const ASSISTANT_RUN_DEADLINE_MS = 90_000;

/** The web client polls an active run this often. */
export const ASSISTANT_POLL_MS = 2_000;

export const ASSISTANT_SOURCES = ["gmail", "whatsapp"] as const satisfies readonly Source[];

export const RUN_KINDS = ["briefing", "prepare"] as const;
export type RunKind = (typeof RUN_KINDS)[number];

export const RUN_STATES = ["running", "succeeded", "failed", "interrupted"] as const;
export type RunState = (typeof RUN_STATES)[number];

/**
 * The bounded, content-free reasons a run ends failed/interrupted (never stderr or input text):
 *   - source_unavailable: a Sheets tab read failed (the old snapshot stays, labelled historical);
 *   - sheets_not_configured: no sheetId / service-account key;
 *   - run_timeout: the 90 s logical deadline passed first;
 *   - shutdown: the server closed while the run was in flight (state interrupted);
 *   - abandoned: found `running` at startup after its owner died (state interrupted);
 *   - compose_*: reserved for preparation (Step 10);
 *   - internal: anything else.
 */
export const RUN_ERROR_CODES = [
  "source_unavailable",
  "sheets_not_configured",
  "run_timeout",
  "shutdown",
  "abandoned",
  "compose_timeout",
  "compose_invalid",
  "compose_failed",
  "internal",
] as const;
export type RunErrorCode = (typeof RUN_ERROR_CODES)[number];

/** How fresh a source's stored tasks are. S1 never claims connector sync time: always unknown. */
export const SOURCE_FRESHNESS = ["unknown"] as const;
export type SourceFreshness = (typeof SOURCE_FRESHNESS)[number];

/** The existing Todo fields a briefing item cites, copied verbatim (never guessed). */
export interface SourceRef {
  todoId: string;
  source: Source;
  sender: string;
  context: string;
  messageDate: string;
  link: string;
  /** The Todo's bounded `original_text` excerpt, not the full conversation. */
  originalText: string;
  action: string;
  extractionStatus: ExtractionStatus;
}

export interface BriefingItem {
  sourceRef: SourceRef;
  /** Newly visible in this capped briefing vs the immediately preceding successful snapshot. */
  isNew: boolean;
  /** Only `extractionStatus: done` items can be prepared. */
  preparationEligible: boolean;
}

export interface SourceCoverage {
  source: Source;
  /** From files present only (pipeline/configured.ts); never a secret value. */
  configured: boolean;
  freshness: SourceFreshness;
}

/** An immutable briefing snapshot. */
export interface Briefing {
  id: string;
  createdAt: string;
  /** When the Todos + Quarantine tabs were read (never connector sync time). */
  sheetReadAt: string;
  /** The preceding successful snapshot; null for the first (baseline) briefing. */
  previousBriefingId: string | null;
  /** Every open, visible to-do (not just the shown ones). */
  openCount: number;
  /** openCount minus the shown items. */
  omittedCount: number;
  items: BriefingItem[];
  sourceCoverage: SourceCoverage[];
}

export interface AssistantRun {
  id: string;
  requestId: string;
  kind: RunKind;
  state: RunState;
  createdAt: string;
  finishedAt: string | null;
  /** Briefing (kind briefing) or packet (kind prepare) id of a succeeded run; else null. */
  targetId: string | null;
  sourceTodoId: string | null;
  errorCode: RunErrorCode | null;
  model: string | null;
  promptVersion: string | null;
}

/** POST /api/assistant/briefings body. */
export interface StartBriefingRequest {
  requestId: string;
}

/** POST /api/assistant/briefings (202), GET /api/assistant/runs/:id. */
export interface RunResponse {
  run: AssistantRun;
}

/** GET /api/assistant/runs/latest. */
export interface LatestRunResponse {
  run: AssistantRun | null;
}

/** GET /api/assistant/briefings/latest. */
export interface LatestBriefingResponse {
  briefing: Briefing | null;
}

/** A canonical lowercase/uppercase hex UUID (8-4-4-4-12). */
export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isUuid(value: unknown): value is string {
  return typeof value === "string" && UUID_PATTERN.test(value);
}
